import hmac
import hashlib

def verify_auth_token(token: str, secret: str) -> bool:
    try:
        payload, signature = token.rsplit('.', 1)
        expected = hmac.new(secret.encode(), payload.encode(), hashlib.sha256).hexdigest()
        return hmac.compare_digest(signature, expected)
    except Exception:
        return False

import json
import os

def parse_json_config(file_path: str) -> dict:
    if not os.path.exists(file_path):
        raise FileNotFoundError(f'Config not found: {file_path}')
    with open(file_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def build_user_query(role: str, active_only: bool) -> tuple:
    query = 'SELECT id, username, email FROM users WHERE role = %s'
    params = [role]
    if active_only:
        query += ' AND is_active = %s'
        params.append(True)
    return query, tuple(params)

import socket
import ipaddress
from urllib.parse import urlparse

def validate_and_fetch_webhook(url: str) -> bool:
    try:
        parsed = urlparse(url)
        if parsed.scheme not in ('http', 'https'):
            return False
        hostname = parsed.hostname
        if not hostname:
            return False
        ip_str = socket.gethostbyname(hostname)
        ip = ipaddress.ip_address(ip_str)
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved:
            return False
        return True
    except Exception:
        return False

import hmac
import hashlib

def is_admin_session_valid(session_token: str, db_session_hash: str) -> bool:
    if not session_token or not db_session_hash:
        return False
    token_hash = hashlib.sha256(session_token.encode('utf-8')).hexdigest()
    return hmac.compare_digest(token_hash, db_session_hash)
